        for cell in row:
            if cell.value is not None:
                vals.append(f"{cell.coordinate}={cell.value!r}")
        if vals:
            print(" | ".join(vals))
    print()

import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_letter_to_idx(col_letter):
    idx = 0
    for ch in col_letter:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1  # 0-based

with zipfile.ZipFile('budget.xlsx') as z:
    print("=== Files in archive ===")
    for n in z.namelist():
        print(n)

    # workbook.xml -> sheet names and rIds
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb_root.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

    # workbook.xml.rels -> rId -> target
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root:
        rel_map[rel.get('Id')] = rel.get('Target')

    print("\n=== Sheets ===")
    for name, rid in sheets:
        print(f"{name} -> {rel_map.get(rid)}")

    # shared strings
    shared_strings = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared_strings.append(text)

    print("\n=== Cell contents ===")
    for name, rid in sheets:
        target = rel_map.get(rid)
        if target.startswith('/'):
            target = target.lstrip('/')
        else:
            target = 'xl/' + target
        ws_root = ET.fromstring(z.read(target))
        print(f"\n--- Sheet: {name} ---")
        for row in ws_root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = v.text if v is not None else None
                if t == 's' and val is not None:
                    val = shared_strings[int(val)]
                print(f"{ref} = {val!r} (type={t})")

