import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    ws_root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = {}
for row in ws_root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
    r = int(row.get('r'))
    cells = {}
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        col = ''.join(ch for ch in ref if ch.isalpha())
        t = c.get('t')
        if t == 'inlineStr':
            is_el = c.find('m:is', NS)
            val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        else:
            v = c.find('m:v', NS)
            val = v.text if v is not None else None
        cells[col] = val
    rows[r] = cells

def num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return 0.0

expense_rows = [(r, rows[r].get('A'), rows[r].get('B'), rows[r].get('C')) for r in range(11, 23)]
total = sum(num(c) for _, _, _, c in expense_rows)

print("=== Expense line items (rows 11-22) ===")
cat_totals = {}
for r, cat, sub, amt in expense_rows:
    a = num(amt)
    cat_totals[cat] = cat_totals.get(cat, 0.0) + a
    print(f"row {r}: {cat!r:20} | {sub!r:20} | {amt!r:8} -> {a:g}")

print("\n=== Totals by category ===")
for cat, tot in cat_totals.items():
    print(f"{cat:20} {tot:g}")
print(f"\nTOTAL EXPENSES (C11:C22) = {total:g}")

income_rows = [(r, rows[r].get('A'), rows[r].get('B')) for r in range(4, 8)]
print("\n=== Income line items (rows 4-7) ===")
inc_total = 0.0
for r, label, amt in income_rows:
    a = num(amt)
    inc_total += a
    print(f"row {r}: {label!r:20} | {amt!r:8} -> {a:g}")
print(f"TOTAL INCOME = {inc_total:g}")

